import React, { useEffect } from "react";
import { FiUser, FiShoppingCart, FiArrowRight, FiX } from "react-icons/fi";
import { FaRegHospital } from "react-icons/fa";
import "./LoginRoleModal.css";

const LoginRoleModal = ({ isOpen, onClose, onSelectRole }) => {
  // Lock background scroll when modal is open
  useEffect(() => {
    if (isOpen) {
      const originalBodyOverflow = document.body.style.overflow;
      const originalDocOverflow = document.documentElement.style.overflow;
      document.body.style.overflow = "hidden";
      document.documentElement.style.overflow = "hidden";

      const handleKeyDown = (e) => {
        if (e.key === "Escape") {
          onClose();
        }
      };
      window.addEventListener("keydown", handleKeyDown);

      return () => {
        document.body.style.overflow = originalBodyOverflow || "";
        document.documentElement.style.overflow = originalDocOverflow || "";
        window.removeEventListener("keydown", handleKeyDown);
      };
    }
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleRoleClick = (roleKey) => {
    if (onSelectRole) {
      onSelectRole(roleKey);
    }
  };

  return (
    <div
      className="login-role-modal-overlay"
      role="dialog"
      aria-modal="true"
      aria-labelledby="login-role-modal-title"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="login-role-modal-container" onClick={(e) => e.stopPropagation()}>
        {/* Close button */}
        <button
          type="button"
          className="login-role-modal-close"
          onClick={onClose}
          aria-label="Close modal"
        >
          <FiX size={18} />
        </button>

        {/* Header with Logo on Left, Title/Subtitle Centered */}
        <div className="login-role-modal-header">
          <div className="login-role-modal-logo-wrap">
            <img
              src="/assets/images/logo/BHARATLOGO-011.webp"
              alt="4Ceps Logo"
              className="login-role-modal-logo"
            />
          </div>
          <div className="login-role-modal-header-text">
            <h2 id="login-role-modal-title" className="login-role-modal-title">
              Welcome to <span>4Ceps</span>
            </h2>
            <p className="login-role-modal-subtitle">
              Please choose an option to proceed:
            </p>
          </div>
        </div>

        {/* Options Grid (3 Roles) */}
        <div className="login-role-cards-grid">
          {/* Option 1: Patient */}
          <div className="login-role-option-column">
            <div
              className="login-role-image-card patient-image-card"
              role="button"
              tabIndex={0}
              onClick={() => handleRoleClick("patient")}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleRoleClick("patient");
                }
              }}
            >
              <img
                src="/assets/images/patient_login_stock.jpg"
                alt="Patient"
                className="login-role-card-img"
              />
            </div>

            <button
              type="button"
              className="login-role-card-btn patient-btn"
              onClick={() => handleRoleClick("patient")}
            >
              <FiUser size={15} />
              <span>Patient</span>
              <FiArrowRight size={15} />
            </button>
          </div>

          {/* Option 2: Pharmacy */}
          <div className="login-role-option-column">
            <div
              className="login-role-image-card pharmacy-image-card"
              role="button"
              tabIndex={0}
              onClick={() => handleRoleClick("seller")}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleRoleClick("seller");
                }
              }}
            >
              <img
                src="/assets/images/pharmacy_login_stock.jpg"
                alt="Pharmacy"
                className="login-role-card-img"
              />
            </div>

            <button
              type="button"
              className="login-role-card-btn pharmacy-btn"
              onClick={() => handleRoleClick("seller")}
            >
              <FiShoppingCart size={15} />
              <span>Pharmacy</span>
              <FiArrowRight size={15} />
            </button>
          </div>

          {/* Option 3: Hospital */}
          <div className="login-role-option-column">
            <div
              className="login-role-image-card hospital-image-card"
              role="button"
              tabIndex={0}
              onClick={() => handleRoleClick("centre")}
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  handleRoleClick("centre");
                }
              }}
            >
              <img
                src="/assets/images/hospital_login_stock.jpg"
                alt="Hospital"
                className="login-role-card-img"
              />
            </div>

            <button
              type="button"
              className="login-role-card-btn hospital-btn"
              onClick={() => handleRoleClick("centre")}
            >
              <FaRegHospital size={15} />
              <span>Hospital</span>
              <FiArrowRight size={15} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginRoleModal;
